from pathlib import Path
import base64
b=Path.home()/"tj23114/packages/dachuang_ztd/ZhouSiyu_DF_GAN_20261117"
p=b/"uploads/20261122_generative_full_v05_code.tar.gz.part"
assert p.resolve().is_relative_to(b.resolve())
x=base64.b64decode('')
offset=126000
n=p.stat().st_size if p.exists() else 0
if n==offset:
 with p.open("ab") as f:f.write(x)
elif n>=offset+len(x):
 with p.open("rb") as f:f.seek(offset);assert f.read(len(x))==x
else:raise ValueError("Offset mismatch")
print('RUNTIME_V05_CHUNK_3_OK',flush=True)
